    21	#ifndef KIMAGEFORMATS_RLE_P_H
    22	#define KIMAGEFORMATS_RLE_P_H
    23	
    24	#include <QDebug>
    25	#include <QDataStream>
    26	
    27	/**
    28	 * The RLEVariant to use.
    29	 *
    30	 * This mostly concerns what to do values >= 128.
    31	 */
    32	enum class RLEVariant {
    33	    /**
    34	     * PackBits-style RLE
    35	     *
    36	     * Value 128 is ignored, 129 indicates a repetition
    37	     * of size 2, 130 of size 3, up to 255 of size 128.
    38	     */
    39	    PackBits,
    40	    /**
    41	     * PIC-style RLE
    42	     *
    43	     * Value 128 indicates a 16-bit repetition count
    44	     * follows, while 129 indicates a repetition
    45	     * of size 128, 130 of size 127, down to 255 of
    46	     * size 2.
    47	     */
    48	    PIC
    49	};
    50	
    51	/**
    52	 * Decodes data written in run-length encoding format.
    53	 *
    54	 * This is intended to be used with lambda functions.
    55	 *
    56	 * Note that this functions expects that, at the current location in @p stream,
    57	 * exactly @p length items have been encoded as a unit (and so it will not be
    58	 * partway through a run when it has decoded @p length items). If this is not
    59	 * the case, it will return @c false.
    60	 *
    61	 * @param variant     The RLE variant to decode.
    62	 * @param stream      The stream to read the data from.
    63	 * @param buf         The location to write the decoded data.
    64	 * @param length      The number of items to read.
    65	 * @param readData    A function that takes a QDataStream reference and reads a
    66	 *                    single value.
    67	 * @param updateItem  A function that takes an item from @p buf and the result
    68	 *                    of a readData call, and produces the item that should be
    69	 *                    written to @p buf.
    70	 *
    71	 * @returns @c true if @p length items in mixed RLE were successfully read
    72	 *          into @p buf, @c false otherwise.
    73	 */
    74	template<typename Item, typename Func1, typename Func2>
    75	static inline bool decodeRLEData(RLEVariant variant,
    76	                                 QDataStream &stream,
    77	                                 Item *dest,
    78	                                 quint32 length,
    79	                                 Func1 readData,
    80	                                 Func2 updateItem)
    81	{
    82	    unsigned offset = 0; // in dest
    83	    while (offset < length) {
    84	        unsigned remaining = length - offset;
    85	        quint8 count1;
    86	        stream >> count1;
    87	
    88	        if (count1 >= 128u) {
    89	            unsigned length = 0;
    90	            if (variant == RLEVariant::PIC) {
    91	                if (count1 == 128u) {
    92	                    // If the value is exactly 128, it means that it is more than
    93	                    // 127 repetitions
    94	                    quint16 count2;
    95	                    stream >> count2;
    96	                    length = count2;
    97	                } else {
    98	                    // 2 to 128 repetitions
    99	                    length = count1 - 127u;
   100	                }
   101	            } else if (variant == RLEVariant::PackBits) {
   102	                if (count1 == 128u) {
   103	                    // Ignore value 128
   104	                    continue;
   105	                } else {
   106	                    // 128 to 2 repetitions
   107	                    length = 257u - count1;
   108	                }
   109	            } else {
   110	                Q_ASSERT(false);
   111	            }
   112	            if (length > remaining) {
   113	                qDebug() << "Row overrun:" << length << ">" << remaining;
   114	                return false;
   115	            }
   116	            auto datum = readData(stream);
   117	            for (unsigned i = offset; i < offset + length; ++i) {
   118	                dest[i] = updateItem(dest[i], datum);
   119	            }
   120	            offset += length;
   121	        } else {
   122	            // No repetitions
   123	            unsigned length = count1 + 1u;
   124	            if (length > remaining) {
   125	                qDebug() << "Row overrun:" << length << ">" << remaining;
   126	                return false;
   127	            }
   128	            for (unsigned i = offset; i < offset + length; ++i) {
   129	                auto datum = readData(stream);
   130	                dest[i] = updateItem(dest[i], datum);
   131	            }
   132	            offset += length;
   133	        }
   134	    }
   135	    if (stream.status() != QDataStream::Ok) {
   136	        qDebug() << "DataStream status was" << stream.status();
   137	    }
   138	    return stream.status() == QDataStream::Ok;
   139	}
