   142	/**
   143	 * Encodes data in run-length encoding format.
   144	 *
   145	 * This is intended to be used with lambda functions.
   146	 *
   147	 * @param variant     The RLE variant to encode in.
   148	 * @param stream      The stream to write the data to.
   149	 * @param data        The data to be written.
   150	 * @param length      The number of items to write.
   151	 * @param itemsEqual  A function that takes two items and returns whether
   152	 *                    @p writeItem would write them identically.
   153	 * @param writeItem   A function that takes a QDataStream reference and an item
   154	 *                    and writes the item to the data stream.
   155	 */
   156	template<typename Item, typename Func1, typename Func2>
   157	static inline void encodeRLEData(RLEVariant variant,
   158	                                 QDataStream &stream,
   159	                                 const Item *data,
   160	                                 unsigned length,
   161	                                 Func1 itemsEqual,
   162	                                 Func2 writeItem)
   163	{
   164	    unsigned offset = 0;
   165	    const unsigned maxEncodableChunk =
   166	        (variant == RLEVariant::PIC)
   167	        ? 65535u
   168	        : 128;
   169	    while (offset < length) {
   170	        const Item *chunkStart = data + offset;
   171	        unsigned maxChunk = qMin(length - offset, maxEncodableChunk);
   172	
   173	        const Item *chunkEnd = chunkStart + 1;
   174	        quint16 chunkLength = 1;
   175	        while (chunkLength < maxChunk && itemsEqual(*chunkStart, *chunkEnd)) {
   176	            ++chunkEnd;
   177	            ++chunkLength;
   178	        }
   179	
   180	        if (chunkLength > 128) {
   181	            // Sequence of > 128 identical pixels
   182	            Q_ASSERT(variant == RLEVariant::PIC);
   183	            stream << quint8(128);
   184	            stream << quint16(chunkLength);
   185	            writeItem(stream, *chunkStart);
   186	        } else if (chunkLength > 1) {
   187	            // Sequence of <= 128 identical pixels
   188	            quint8 encodedLength;
   189	            if (variant == RLEVariant::PIC) {
   190	                encodedLength = quint8(chunkLength + 127);
   191	            } else if (variant == RLEVariant::PackBits) {
   192	                encodedLength = quint8(257 - chunkLength);
   193	            } else {
   194	                Q_ASSERT(false);
   195	                encodedLength = 0;
   196	            }
   197	            stream << encodedLength;
   198	            writeItem(stream, *chunkStart);
   199	        } else {
   200	            // find a string of up to 128 values, each different from the one
   201	            // that follows it
   202	            if (maxChunk > 128) {
   203	                maxChunk = 128;
   204	            }
   205	            chunkLength = 1;
   206	            chunkEnd = chunkStart + 1;
   207	            while (chunkLength < maxChunk &&
   208	                    (chunkLength + 1u == maxChunk ||
   209	                     !itemsEqual(*chunkEnd, *(chunkEnd+1))))
   210	            {
   211	                ++chunkEnd;
   212	                ++chunkLength;
   213	            }
   214	            stream << quint8(chunkLength - 1);
   215	            for (unsigned i = 0; i < chunkLength; ++i) {
   216	                writeItem(stream, *(chunkStart + i));
   217	            }
   218	        }
   219	        offset += chunkLength;
   220	    }
   221	}
